INSERT OR REPLACE INTO property_listings (id, owner_user_id, title, slug, description, listing_purpose, property_type, property_subtype, status, price_amount, price_label, price_visibility, currency, price_period, division, district, city, area_name, address_line, display_address, map_lat, map_lng, bedrooms, bathrooms, balconies, parking_spaces, floor_number, total_floors, size_value, size_unit, land_size_value, land_size_unit, plot_type, facing, handover_status, handover_date, furnishing_status, amenities_json, nearby_places_json, owner_note, admin_note, featured, approved_by_user_id, approved_at, published_at, rejected_at, unpublished_at, created_at, updated_at) VALUES (13, 7, 'Bright Family Flat for Sale in Gulshan', 'pb-demo-gulshan-apartment-01', 'This flat for sale in Gulshan, Dhaka is added for buyers who want a clear and useful starting point instead of a thin listing with only a price and one line. This is a premium Dhaka address, so I would judge it by road access, lift quality, parking, security and how close it sits to Gulshan 1, Gulshan 2 and diplomatic side roads. The size is around 1485 sqft, with 3 rooms and 3 bathrooms. The layout is planned for normal Dhaka living, so I would check light, ventilation, stair and lift condition, parking access, generator backup and the final usable space during viewing.

For a buyer, the good part of this listing is the location logic. It is not only about the building. You should compare how quickly you can reach main roads, schools, hospitals, mosque, kitchen market, office routes and daily transport. If you are looking for flat in Gulshan, keep this one beside two or three nearby options and compare them honestly.

My simple advice is this: visit in daylight, ask for ownership papers, check utility bills, confirm parking, and do not decide only from photos. PropertyBikri keeps the listing easy to scan, but the final decision should come after a proper visit and document check.', 'sale', 'apartment', 'flat', 'approved', NULL, 'Call for details', 'call_for_price', 'BDT', NULL, 'Dhaka', 'Dhaka', 'Dhaka', 'Gulshan', 'Gulshan residential area', 'Gulshan, Dhaka', 23.7932, 90.4085, 3, 3, 2, 1, 1, 11, 1485.0, 'sqft', NULL, 'katha', NULL, 'East', 'ready', 'Ready for viewing', 'semi_furnished', '["Generator Backup", "Security Staff", "CCTV Security", "Parking", "Gas Line", "Community Space"]', '["Gulshan 1", "Gulshan 2", "Banani", "Baridhara"]', NULL, NULL, 1, 1, '2026-08-04T09:48:55Z', '2026-08-04T09:48:55Z', NULL, NULL, '2026-08-04T09:47:57Z', '2026-08-04T10:08:45Z');
